style.css:
button {
  background-color: red;
  color: white; /* Optional: makes the text color white */
  border: none; /* Optional: removes border */
  padding: 10px 20px; /* Optional: adds padding for better look */
  font-size: 16px; /* Optional: sets font size */
  cursor: pointer; /* Optional: makes cursor a hand when hovering */
}

button:hover {
  background-color: darkred; /* Optional: changes color on hover */
}
